<div><?php if($this->session->flashdata('success')):?><p class="alert success"><?=$this->session->flashdata('success')?></p><?php endif;?><p class="eyebrow">MANAGEMENT</p><h2><?=$title?></h2><section class="panel"><table class="table"><tr><th>Client</th><th>Email</th><th>Details</th><th>Status</th><th>Submitted</th><th>Action</th></tr><?php if(empty($rows)):?><tr><td colspan="6" style="text-align:center;color:#8993a8;padding:35px">No records to display.</td></tr><?php endif;?><?php foreach($rows as $row):?><tr><td><?=html_escape($row['first_name'].' '.$row['last_name'])?></td><td><?=html_escape($row['email'])?></td><td><?php if($type==='loans'):?>$<?=number_format($row['amount'],2)?> / <?=$row['term_months']?> months<?php elseif($type==='deposits')?>$<?=number_format($row['amount'],2)?> · <?=html_escape($row['description'])?><?php elseif($type==='cards'||$type==='card-applications'):?><?=ucfirst($row['card_type'])?> · •••• <?=$row['last_four']?><?php else:?><?=html_escape($row['document_type']??'—')?></td><?php endif;?></td><td><span class="badge <?=$row['status']?>"><?=$row['status']?></span></td><td><?=date('M j, Y',strtotime($row['created_at']))?></td><td><?php $approval=($type==='cards'||$type==='card-applications')?'active':'approved';?><a class="button small" href="<?=base_url('admin/'.$type.'/'.$row['id'].'/'.$approval)?>"><?= $approval==='active'?'Activate':'Approve' ?></a> <a style="color:#bd3844;font-size:12px" href="<?=base_url('admin/'.$type.'/'.$row['id'].'/rejected')?>">Reject</a></td></tr><?php endforeach;?></table></section></div>
